import{_ as t,o,c as a,ah as r}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"Research: The Schmid-Benko Chats (The Protocols of Proximity)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/thomas-schmid-chats-details.md","filePath":"en/recherche/thomas-schmid-chats-details.md"}'),h={name:"en/recherche/thomas-schmid-chats-details.md"};function i(s,e,n,c,d,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="research-the-schmid-benko-chats-the-protocols-of-proximity" tabindex="-1">Research: The Schmid-Benko Chats (The Protocols of Proximity) <a class="header-anchor" href="#research-the-schmid-benko-chats-the-protocols-of-proximity" aria-label="Permalink to &quot;Research: The Schmid-Benko Chats (The Protocols of Proximity)&quot;">​</a></h1><p><strong>&quot;You are the whore for the rich!&quot; – Insights into a system of privileged treatment.</strong></p><p>The secured chat messages from Thomas Schmid document a close relationship between top-level politics and large investors that is unprecedented in the Second Republic of Austria. Especially the communication with René Benko provides deep insights into the &quot;aesthetics of intervention.&quot;</p><hr><h2 id="key-quotes-and-events" tabindex="-1">Key Quotes and Events <a class="header-anchor" href="#key-quotes-and-events" aria-label="Permalink to &quot;Key Quotes and Events&quot;">​</a></h2><h3 id="_1-the-whore-for-the-rich" tabindex="-1">1. The &quot;Whore for the Rich&quot; <a class="header-anchor" href="#_1-the-whore-for-the-rich" aria-label="Permalink to &quot;1. The &quot;Whore for the Rich&quot;&quot;">​</a></h3><p>A quote that Schmid wrote in a chat about his own role in the ÖVP cabinet became a catchphrase for allegations of venality:</p><blockquote><p><em>&quot;You&#39;re working in the ÖVP cabinet!! You are the whore for the rich!&quot;</em></p></blockquote><h3 id="_2-the-job-offer-as-currency" tabindex="-1">2. The Job Offer as Currency <a class="header-anchor" href="#_2-the-job-offer-as-currency" aria-label="Permalink to &quot;2. The Job Offer as Currency&quot;">​</a></h3><p>According to Schmid&#39;s testimony, René Benko offered him a position as General Representative at the end of 2016 – with a salary package of up to <strong>600,000 euros per year</strong>. At the same time, Schmid was involved in tax audits of Signa.</p><h3 id="_3-we-are-for-rene-benko" tabindex="-1">3. &quot;We are for René Benko&quot; <a class="header-anchor" href="#_3-we-are-for-rene-benko" aria-label="Permalink to &quot;3. &quot;We are for René Benko&quot;&quot;">​</a></h3><p>In a chat with top officials, Schmid clarified the ministry&#39;s strategy:</p><blockquote><p><em>&quot;We are for René Benko. Think he is coordinated with HBK [Federal Chancellor Kurz].&quot;</em></p></blockquote><hr><p><em>Sources: Interrogation protocols of the WKStA (Thomas Schmid), reporting by Profil, Standard, and ZackZack.</em></p>',15)])])}const f=t(h,[["render",i]]);export{u as __pageData,f as default};
